def fib_mod(n, mod=1_000_000_007):
    def _fib(k):
        if k == 0:
            return (0, 1)
        a, b = _fib(k // 2)
        c = (a * ((b * 2 - a) % mod)) % mod
        d = (a * a + b * b) % mod
        if k % 2 == 0:
            return (c, d)
        else:
            return (d, (c + d) % mod)
    return _fib(n)[0]

